// Node 3 - Generate Dashboard Summary
const items = $input.all();
const alerts = items.map(item => item.json);

const total = alerts.length;

const norm = (v) => (v || '').toString().trim().toLowerCase();

const highAlerts = alerts.filter(a => norm(a.severity) === 'high').length;
const mediumAlerts = alerts.filter(a => norm(a.severity) === 'medium').length;
const lowAlerts = alerts.filter(a => norm(a.severity) === 'low').length;

const riskScores = alerts
  .map(a => Number(a.risk_score))
  .filter(n => !isNaN(n));

const avgRiskScore = riskScores.length
  ? (riskScores.reduce((sum, n) => sum + n, 0) / riskScores.length).toFixed(2)
  : '0.00';

// Query already orders by created_at DESC, so first row is latest
const latest = alerts[0] || {};
const latestIncident = latest.incident_id || 'N/A';

// Find highest risk incident
let highestRiskAlert = null;
for (const a of alerts) {
  const score = Number(a.risk_score);
  if (isNaN(score)) continue;
  if (!highestRiskAlert || score > Number(highestRiskAlert.risk_score)) {
    highestRiskAlert = a;
  }
}
const highestRiskIncident = highestRiskAlert ? highestRiskAlert.incident_id : 'N/A';
const highestRiskScore = highestRiskAlert ? highestRiskAlert.risk_score : 'N/A';

const generatedTime = new Date().toISOString();

// Pre-build HTML table rows (top 25 most recent alerts)
const escapeHtml = (str) => {
  if (str === null || str === undefined) return '';
  return str.toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

const severityColor = (sev) => {
  const s = norm(sev);
  if (s === 'high') return '#e53935';
  if (s === 'medium') return '#fb8c00';
  if (s === 'low') return '#43a047';
  return '#757575';
};

const tableRows = alerts.length
  ? alerts.slice(0, 25).map(a => `
  <tr>
    <td>${escapeHtml(a.incident_id)}</td>
    <td><span style="color:${severityColor(a.severity)};font-weight:600;">${escapeHtml(a.severity)}</span></td>
    <td>${escapeHtml(a.priority)}</td>
    <td>${escapeHtml(a.threat_category)}</td>
    <td>${escapeHtml(a.risk_score)}</td>
    <td>${escapeHtml(a.status)}</td>
    <td>${escapeHtml(a.created_at)}</td>
  </tr>`).join('')
  : '<tr><td colspan="7" style="text-align:center;color:#9e9e9e;padding:16px;">No alerts found</td></tr>';

return [
  {
    json: {
      totalAlerts: total,
      highAlerts,
      mediumAlerts,
      lowAlerts,
      avgRiskScore,
      latestIncident,
      highestRiskIncident,
      highestRiskScore,
      generatedTime,
      tableRows,
      alertCountShown: Math.min(alerts.length, 25)
    }
  }
];
